import AppLayout from "@/components/AppLayout.vue";
import request from "@/utils/axios"; // 导入配置好的axios实例

export default {
  name: "ReportDetailView",
  components: {
    AppLayout
  },
  data() {
    return {
      reportId: null,
      doctorNotes: "",
      treatmentPlan: "",
      isEditing: false,
      isPrinting: false,
      diseaseCategories: ["糖尿病视网膜病变", "青光眼", "白内障", "AMD", "高血压视网膜病变", "近视", "其他异常", "正常"],
      report: {
        id: "",
        diagnosisTime: "",
        time: "",
        doctor: "",
        leftEyeImage: "",
        rightEyeImage: "",
        leftEye: {
          diagnosis: "",
          confidence: 0,
          probabilities: []
        },
        rightEye: {
          diagnosis: "",
          confidence: 0,
          probabilities: []
        },
        finalDiagnosis: "",
        suggestion: ""
      },
      patientInfo: {
        name: "",
        gender: "",
        age: 0
      },
      isLoading: true,
      appliedScale: 1
    };
  },
  computed: {
    formattedDate() {
      const now = new Date();
      return `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日`;
    }
  },
  methods: {
    goBack() {
      this.$router.go(-1);
    },
    exportReport() {
      this.isPrinting = true;
      this.$nextTick(() => {
        // 准备打印环境
        const originalTitle = document.title;
        document.title = `眼科诊断报告-患者${this.reportId}-${new Date().toLocaleDateString()}`;

        // 禁用所有非报告元素
        const header = document.querySelector("header");
        const nav = document.querySelector("nav");
        const footer = document.querySelector("footer");
        const appLayout = document.querySelector(".app-layout");
        const reportContent = this.$refs.reportContent;
        if (header) header.style.display = "none";
        if (nav) nav.style.display = "none";
        if (footer) footer.style.display = "none";
        if (appLayout) appLayout.style.padding = "0";

        // 设置报告容器样式确保单页打印
        if (reportContent) {
          reportContent.style.overflow = "visible";
          reportContent.style.height = "auto";
        }

        // 添加专门的打印样式类
        document.body.classList.add("printing-report");

        // 自动调整缩放比例
        this.adjustPrintScale();

        // 执行打印
        window.print();

        // 还原环境
        document.title = originalTitle;
        if (header) header.style.display = "";
        if (nav) nav.style.display = "";
        if (footer) footer.style.display = "";
        if (appLayout) appLayout.style.padding = "";
        if (reportContent) {
          reportContent.style.overflow = "";
          reportContent.style.height = "";
        }

        // 移除打印样式类
        document.body.classList.remove("printing-report");

        // 重置缩放比例
        this.resetPrintScale();
        this.$message.success("报告已导出为PDF文件");
        this.isPrinting = false;
      });
    },
    printReport() {
      this.isPrinting = true;
      this.$nextTick(() => {
        // 准备打印环境
        const originalTitle = document.title;
        document.title = `眼科诊断报告-患者${this.reportId}-${new Date().toLocaleDateString()}`;

        // 禁用所有非报告元素
        const header = document.querySelector("header");
        const nav = document.querySelector("nav");
        const footer = document.querySelector("footer");
        const appLayout = document.querySelector(".app-layout");
        const reportContent = this.$refs.reportContent;
        if (header) header.style.display = "none";
        if (nav) nav.style.display = "none";
        if (footer) footer.style.display = "none";
        if (appLayout) appLayout.style.padding = "0";

        // 设置报告容器样式确保单页打印
        if (reportContent) {
          reportContent.style.overflow = "visible";
          reportContent.style.height = "auto";
        }

        // 添加专门的打印样式类
        document.body.classList.add("printing-report");

        // 自动调整缩放比例
        this.adjustPrintScale();

        // 执行打印
        window.print();

        // 还原环境
        document.title = originalTitle;
        if (header) header.style.display = "";
        if (nav) nav.style.display = "";
        if (footer) footer.style.display = "";
        if (appLayout) appLayout.style.padding = "";
        if (reportContent) {
          reportContent.style.overflow = "";
          reportContent.style.height = "";
        }

        // 移除打印样式类
        document.body.classList.remove("printing-report");

        // 重置缩放比例
        this.resetPrintScale();
        this.isPrinting = false;
      });
    },
    startEdit() {
      this.isEditing = true;
    },
    cancelEdit() {
      this.isEditing = false;
    },
    saveTreatmentPlan() {
      // 如果没有修改，直接返回
      if (!this.treatmentPlan) {
        this.$message.warning("请先填写治疗方案");
        return;
      }

      // 发送请求保存治疗方案
      request({
        method: "get",
        url: "/diagnose/saveTreatmentPlan",
        params: {
          patientId: this.reportId,
          treatmentPlan: this.treatmentPlan
        }
      }).then(response => {
        if (response.code === 0 || response.code === 200 || response.code === 1) {
          this.$message.success("治疗方案已保存");
          this.isEditing = false;
        } else {
          this.$message.error(response.msg || "保存失败，请稍后重试");
        }
      }).catch(error => {
        console.error("保存治疗方案出错:", error);
        this.$message.error("保存失败，请稍后重试");
      });
    },
    saveNotes() {
      if (!this.doctorNotes) {
        this.$message.warning("请先填写医生备注");
        return;
      }

      // 发送请求保存医生备注
      request({
        method: "post",
        url: "/diagnose/saveDoctorNotes",
        data: {
          patientId: this.reportId,
          doctorNotes: this.doctorNotes
        }
      }).then(response => {
        if (response.code === 0 || response.code === 200 || response.code === 1) {
          this.$message.success("医生备注已保存");
        } else {
          this.$message.error(response.msg || "保存失败，请稍后重试");
        }
      }).catch(error => {
        console.error("保存医生备注出错:", error);
        this.$message.error("保存失败，请稍后重试");
      });
    },
    percentFormat(percentage) {
      return percentage + "%";
    },
    getConfidenceColor(confidence) {
      if (confidence >= 80) {
        return "#67c23a"; // 高置信度，绿色
      } else if (confidence >= 60) {
        return "#e6a23c"; // 中等置信度，黄色
      } else {
        return "#f56c6c"; // 低置信度，红色
      }
    },
    getMatrixData(probabilities) {
      if (!probabilities || probabilities.length === 0) {
        return [];
      }
      return this.diseaseCategories.map((disease, index) => ({
        disease,
        probability: Math.round(probabilities[index] * 100)
      }));
    },
    generateRandomProbabilities() {
      // 生成随机概率分布
      const probs = Array(this.diseaseCategories.length).fill(0).map(() => Math.random());
      const sum = probs.reduce((a, b) => a + b, 0);
      return probs.map(p => p / sum);
    },
    getMaxProbabilityIndex(probabilities) {
      return probabilities.indexOf(Math.max(...probabilities));
    },
    generateFinalDiagnosis(leftIndex, rightIndex) {
      // 根据左右眼结果生成综合诊断
      if (leftIndex === rightIndex) {
        return `双眼${this.diseaseCategories[leftIndex]}`;
      } else if (leftIndex === 7 || rightIndex === 7) {
        // 7是"正常"的索引
        const abnormalIndex = leftIndex === 7 ? rightIndex : leftIndex;
        const abnormalSide = leftIndex === 7 ? "右眼" : "左眼";
        return `${abnormalSide}${this.diseaseCategories[abnormalIndex]}，另眼正常`;
      } else {
        return `左眼${this.diseaseCategories[leftIndex]}，右眼${this.diseaseCategories[rightIndex]}`;
      }
    },
    generateSuggestionFromDiagnosis(leftDiagnosis, rightDiagnosis) {
      // 根据诊断结果生成建议
      const suggestions = {
        糖尿病视网膜病变: "建议进行血糖控制，定期复查眼底，必要时考虑激光或抗VEGF治疗。",
        青光眼: "建议测量眼压，进行视野检查，必要时使用降眼压药物。",
        白内障: "建议进行视力矫正，必要时考虑白内障手术。",
        AMD: "建议定期监测黄斑区变化，必要时考虑抗VEGF治疗。",
        高血压视网膜病变: "建议控制血压，定期复查眼底。",
        近视: "建议进行屈光矫正，控制近距离用眼时间。",
        其他异常: "建议进一步检查确定具体异常类型。",
        正常: "眼底未见明显异常，建议定期检查。"
      };

      // 确保诊断结果有值并存在于预设的建议方案中
      const leftTreatment = suggestions[leftDiagnosis] || "请遵医嘱进行治疗。";
      const rightTreatment = suggestions[rightDiagnosis] || "请遵医嘱进行治疗。";
      if (leftDiagnosis === rightDiagnosis) {
        return leftTreatment;
      } else {
        return `左眼：${leftTreatment}\n右眼：${rightTreatment}`;
      }
    },
    async loadReportData() {
      try {
        // 获取路由中的报告ID
        const patientId = this.$route.params.id;

        // 调用API获取诊断报告数据 - 修改为GET请求
        const response = await request({
          method: "get",
          url: "/diagnose/report",
          params: {
            patientId: patientId
          }
        });
        if (response.code === 0 || response.code === 1 || response.code === 200) {
          const data = response.data;
          console.log("Received report data:", data);

          // 设置患者信息
          this.patientInfo = {
            name: data.patientMsg?.name || "",
            gender: data.patientMsg?.gender || "male",
            age: data.patientMsg?.age || 0
          };

          // 解析图像路径
          const leftImagePath = data.result?.imageLeft || data.imageLeft || "";
          const rightImagePath = data.result?.imageRight || data.imageRight || "";

          // 解析概率数组和标签
          const leftProbabilities = data.result?.diseaseLeftProbabilities || [];
          const rightProbabilities = data.result?.diseaseRightProbabilities || [];
          const leftLabels = data.result?.diseaseLeftLabels || [];
          const rightLabels = data.result?.diseaseRightLabels || [];

          // 如果API返回了标签和概率，将它们组合成对象数组
          let formattedLeftProbs = this.formatProbabilities(leftProbabilities, leftLabels);
          let formattedRightProbs = this.formatProbabilities(rightProbabilities, rightLabels);

          // 设置报告数据
          this.report = {
            id: data.patientMsg?.patientId || data.patientId || "",
            diagnosisTime: data.diagnosisTime || "",
            time: data.diagnosisTime || "",
            doctor: "主治医师",
            leftEyeImage: leftImagePath,
            rightEyeImage: rightImagePath,
            leftEye: {
              diagnosis: data.result?.leftResult || data.leftResult || "",
              confidence: 0,
              probabilities: formattedLeftProbs
            },
            rightEye: {
              diagnosis: data.result?.rightResult || data.rightResult || "",
              confidence: 0,
              probabilities: formattedRightProbs
            },
            finalDiagnosis: data.result?.finalResult || data.finalResult || "",
            suggestion: this.generateSuggestionFromDiagnosis(data.result?.leftResult || data.leftResult || "", data.result?.rightResult || data.rightResult || "")
          };

          // 设置初始治疗方案
          this.treatmentPlan = this.report.suggestion;
        } else {
          this.$message.error(response.msg || "获取诊断报告失败");
        }
      } catch (error) {
        console.error("获取诊断报告错误:", error);
        this.$message.error("获取诊断报告失败，请稍后重试");
      } finally {
        this.isLoading = false;
      }
    },
    // 格式化概率数据
    formatProbabilities(probabilities, labels) {
      // 如果没有概率或标签数据，返回空数组
      if (!probabilities || !Array.isArray(probabilities) || probabilities.length === 0) {
        return [];
      }

      // 如果已经是对象数组格式，直接返回
      if (typeof probabilities[0] !== "number" && probabilities[0] && "name" in probabilities[0]) {
        return probabilities;
      }

      // 如果有概率数据（数字数组）但没有标签数据，使用默认疾病分类
      if (!labels || !Array.isArray(labels) || labels.length === 0) {
        return probabilities.map((prob, index) => ({
          name: index < this.diseaseCategories.length ? this.diseaseCategories[index] : `疾病${index + 1}`,
          probability: prob
        }));
      }

      // 将概率和标签组合成对象数组
      return probabilities.map((prob, index) => ({
        name: index < labels.length ? labels[index] : `疾病${index + 1}`,
        probability: prob
      }));
    },
    getTopFiveDiseases(probabilities) {
      // 检查概率数组是否有效
      if (!probabilities || !Array.isArray(probabilities) || probabilities.length === 0) {
        return [];
      }
      let diseaseData = [];

      // 处理不同格式的概率数据
      if (typeof probabilities[0] === "number") {
        // 如果是数字数组格式，按照原来的方式处理
        diseaseData = this.diseaseCategories.map((disease, index) => ({
          disease,
          probability: index < probabilities.length ? Math.round(probabilities[index] * 100) : 0
        }));
      } else if (probabilities[0] && ("name" in probabilities[0] || "probability" in probabilities[0])) {
        // 如果是包含name和probability字段的对象数组
        diseaseData = probabilities.map(item => ({
          disease: item.name || "",
          probability: typeof item.probability === "number" ? Math.round(item.probability * 100) : Math.round(parseFloat(item.probability || 0) * 100)
        }));
      }

      // 按概率从高到低排序
      return diseaseData.sort((a, b) => b.probability - a.probability).slice(0, 5);
    },
    tableCellClassName({
      row,
      column
    }) {
      // 根据概率高低设置不同的颜色样式
      if (column.property === "probability") {
        const prob = row.probability;
        if (prob >= 80) {
          return "high-probability";
        } else if (prob >= 60) {
          return "medium-probability";
        } else if (prob >= 30) {
          return "low-probability";
        }
      }
      return "";
    },
    formatTime(timeString) {
      if (!timeString) return "";
      try {
        const date = new Date(timeString);
        if (isNaN(date.getTime())) return timeString; // Return original if invalid

        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        const seconds = String(date.getSeconds()).padStart(2, "0");
        return `${year}/${month}/${day} ${hours}:${minutes}:${seconds}`;
      } catch (error) {
        console.error("Error formatting time:", error);
        return timeString; // Return original on error
      }
    },
    // 自动调整报告内容缩放以适应一页打印
    adjustPrintScale() {
      const reportPaper = document.querySelector(".report-paper");
      const a4Container = document.querySelector(".a4-container");
      if (!reportPaper || !a4Container) return;

      // 重置容器样式以确保正确测量
      a4Container.style.height = "auto";
      a4Container.style.minHeight = "auto";
      a4Container.style.maxHeight = "none";
      a4Container.style.overflow = "visible";
      reportPaper.style.height = "auto";
      reportPaper.style.transform = "";

      // 为更准确测量，先等待DOM更新
      setTimeout(() => {
        // 测量内容高度（像素）
        const contentHeight = reportPaper.offsetHeight;

        // A4纸高度 (297mm)，转为像素（假设96dpi，1英寸=25.4mm）
        // 297mm ≈ 1123px
        const a4HeightPx = 1123;
        const maxContentHeightPx = a4HeightPx - 40; // 留一些边距空间

        console.log(`报告内容高度: ${contentHeight}px, A4高度限制: ${maxContentHeightPx}px`);
        if (contentHeight > maxContentHeightPx) {
          // 计算需要的缩放比例，确保内容适合A4纸高度
          const scale = maxContentHeightPx / contentHeight;

          // 应用缩放
          reportPaper.style.transform = `scale(${scale})`;
          reportPaper.style.transformOrigin = "top center";

          // 调整容器高度以匹配缩放后的内容
          const scaledHeight = contentHeight * scale;
          a4Container.style.height = `${scaledHeight}px`;

          // 保存缩放值
          this.appliedScale = scale;
          console.log(`应用缩放比例: ${scale}, 缩放后高度: ${scaledHeight}px`);
        } else {
          // 如果内容已经适合页面，确保容器高度正确
          a4Container.style.height = `${contentHeight}px`;
          console.log("内容已适合页面，无需缩放");
        }
      }, 100);
    },
    // 重置报告缩放
    resetPrintScale() {
      const reportPaper = document.querySelector(".report-paper");
      const a4Container = document.querySelector(".a4-container");
      if (reportPaper) {
        reportPaper.style.transform = "";
        reportPaper.style.transformOrigin = "";
      }
      if (a4Container) {
        a4Container.style.height = "";
        a4Container.style.minHeight = "";
        a4Container.style.maxHeight = "";
      }
    }
  },
  created() {
    // 从路由参数获取报告ID
    this.reportId = this.$route.params.id;
    this.loadReportData();

    // 确保isPrinting初始化为false
    this.isPrinting = false;

    // 检查URL参数是否包含print=true，如果是则自动打印
    if (this.$route.query.print === "true") {
      // 等待数据加载完成
      this.$nextTick(() => {
        // 给页面一些时间渲染
        setTimeout(() => {
          this.printReport();
        }, 1000);
      });
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 监听打印事件
    window.addEventListener("beforeprint", () => {
      this.isPrinting = true;
    });
    window.addEventListener("afterprint", () => {
      this.isPrinting = false;
    });
  },
  beforeUnmount() {
    // 移除打印事件监听
    window.removeEventListener("beforeprint", () => {
      this.isPrinting = true;
    });
    window.removeEventListener("afterprint", () => {
      this.isPrinting = false;
    });
  }
};
